/* ==== INTERFACE ====
方向：生物学与科学图解方向（结合 Eco-Nature 与精确生理图解）。底色为清爽淡雅的灰绿/米纸白（#F4F7F4），搭配深叶绿正文（#182B1E）与叶绿素/能量流动色（叶绿翠绿 #2A7E43、ATP/光能金黄 #D9822B、光合代谢青水蓝 #2B7A8C），以及限制因素对比暖红（#C04B32）。字形兼顾亲和力与高一学生教材的准确易读性：中文大标题与强调采用 LXGW WenKai，英文配 Fraunces，正文与科学公式/标签采用清晰坚实的 Noto Sans SC 与 Inter。
token --bg: #F4F7F4 (页面底色，浅色灰绿纸感)
token --text: #182B1E (正文深林青墨)
token --muted: #56695C (辅助说明与次要标签)
token --accent-green: #2A7E43 (光反应、类囊体、叶绿素主强调色)
token --accent-gold: #D9822B (光能、ATP/NADPH能量流动与限制因子线)
token --accent-blue: #2B7A8C (水光解、碳流反应、物质传递)
token --accent-red: #C04B32 (高温失活、极端抑制与警示)
token --font-title: "NTF-fraunces", "NTF-lxgw-wenkai", serif
token --font-sans: "NTF-inter", "NTF-noto-sans-sc", sans-serif
token --font-mono: "NTF-inter", monospace
字阶角色：
--fs-display: 48px / 1.15 (封面与开篇强调标题)
--fs-h1: 34px / 1.25 (普通页主标题)
--fs-h2: 24px / 1.35 (区块/模块标题)
--fs-lead: 18px / 1.6 (导引段落与关键设问)
--fs-body: 16px / 1.65 (正文与机制说明)
--fs-label: 14px / 1.4 (图解节点标注、参数标签、交互控件)
--fs-tick: 12px / 1.2 (坐标轴刻度与方程式角标)
class .nt-title: 普通页题名，默认 font-family: var(--font-title); font-size: var(--fs-h1); font-weight: 500; color: var(--text)。
class .nt-subtitle: 题名下方导引/设问，font-size: var(--fs-lead); color: var(--muted)。
class .nt-card: 局部观察窗/机制图解底板（白底半透微边框与柔和阴影，不作卡片墙，只用于承载反应式或图解区域）。
class .nt-controls: 探究调节滑块/按钮组区域，具名按钮 .nt-btn 与选中状态 [aria-pressed="true"]。
class .nt-chart: 曲线与图表共享样式（光照、CO₂、温度对速率影响曲线），线宽 3px，填充 fill:none，文字使用 var(--font-sans)。
variant opening: html[data-variant="opening"] #stage 采用沉浸深林绿底色（#0C1D13），标题文字高亮米白（#F0F6F1），适合光合作用开篇视觉冲击与引入。
默认：不设 data-variant，为清亮透气的白昼叶绿实验室纸质微光底色。
品牌：无。
==== /INTERFACE ==== */

/* ---- 字体声明 ---- */
@font-face {
  font-family: "NTF-lxgw-wenkai";
  src: url("fonts/library/lxgw-wenkai/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-lxgw-wenkai";
  src: url("fonts/library/lxgw-wenkai/face-1.ttf");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-fraunces";
  src: url("fonts/library/fraunces/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

/* ---- 根 Token 定义 ---- */
:root {
  --bg: #F4F7F4;
  --bg-subtle: #EAEFEA;
  --text: #182B1E;
  --muted: #56695C;
  --border: rgba(30, 58, 40, 0.12);
  --border-strong: rgba(30, 58, 40, 0.28);
  --focus: #2A7E43;

  /* 生物学过程特征语义色彩 */
  --accent-green: #2A7E43;
  --accent-green-subtle: rgba(42, 126, 67, 0.12);
  --accent-gold: #D9822B;
  --accent-gold-subtle: rgba(217, 130, 43, 0.12);
  --accent-blue: #2B7A8C;
  --accent-blue-subtle: rgba(43, 122, 140, 0.12);
  --accent-red: #C04B32;
  --accent-red-subtle: rgba(192, 75, 50, 0.12);

  /* 字体族 */
  --font-title: "NTF-fraunces", "NTF-lxgw-wenkai", serif;
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", sans-serif;
  --font-mono: "NTF-inter", monospace;

  /* 字阶与排版比例 (固定画布设计) */
  --fs-display: 48px;
  --fs-h1: 34px;
  --fs-h2: 24px;
  --fs-lead: 18px;
  --fs-body: 16px;
  --fs-label: 14px;
  --fs-tick: 12px;

  --lh-tight: 1.2;
  --lh-title: 1.28;
  --lh-body: 1.65;

  /* 投影与圆角规范 */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-soft: 0 4px 20px -2px rgba(24, 43, 30, 0.06);
  --shadow-card: 0 6px 24px -4px rgba(24, 43, 30, 0.08);
}

/* ---- 默认舞台背景与氛围 ---- */
#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(ellipse 900px 600px at 15% 10%, rgba(206, 230, 211, 0.45) 0%, transparent 70%),
    radial-gradient(ellipse 800px 500px at 85% 90%, rgba(235, 240, 222, 0.4) 0%, transparent 65%),
    linear-gradient(to bottom, transparent 0%, rgba(230, 238, 230, 0.3) 100%);
  background-repeat: no-repeat;
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

/* ---- 开篇变体 (Opening Variant: 深林暗底沉浸氛围) ---- */
html[data-variant="opening"] {
  --bg: #0C1D13;
  --text: #F0F6F1;
  --muted: #95ADA0;
  --border: rgba(149, 173, 160, 0.2);
  --border-strong: rgba(149, 173, 160, 0.4);
  --accent-green-subtle: rgba(62, 179, 97, 0.2);
  --accent-gold-subtle: rgba(245, 166, 68, 0.2);
}

html[data-variant="opening"] #stage {
  background-color: #0C1D13;
  background-image: 
    radial-gradient(ellipse 1000px 700px at 50% 20%, rgba(20, 54, 34, 0.8) 0%, transparent 70%),
    radial-gradient(ellipse 600px 500px at 80% 85%, rgba(12, 38, 24, 0.6) 0%, transparent 60%);
}

/* ---- 标题与排版类 ---- */
.nt-title {
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 500;
  line-height: var(--lh-title);
  color: var(--text);
  margin: 0 0 10px 0;
  letter-spacing: -0.01em;
}

.nt-title:lang(zh) {
  font-family: "NTF-lxgw-wenkai", serif;
  font-weight: 500;
}

.nt-display {
  font-family: var(--font-title);
  font-size: var(--fs-display);
  font-weight: 500;
  line-height: var(--lh-tight);
  color: var(--text);
  margin: 0 0 14px 0;
}

.nt-subtitle {
  font-size: var(--fs-lead);
  line-height: 1.5;
  color: var(--muted);
  margin: 0 0 24px 0;
}

.nt-h2 {
  font-family: var(--font-title);
  font-size: var(--fs-h2);
  font-weight: 500;
  line-height: 1.35;
  color: var(--text);
  margin: 0 0 8px 0;
}

.nt-body {
  font-size: var(--fs-body);
  line-height: var(--lh-body);
  color: var(--text);
  margin: 0 0 16px 0;
}

.nt-muted {
  color: var(--muted);
}

.nt-caption {
  font-size: var(--fs-label);
  line-height: 1.45;
  color: var(--muted);
}

/* ---- 生物图解与实验面板基础 ---- */
.nt-card {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  padding: 24px;
  box-sizing: border-box;
}

html[data-variant="opening"] .nt-card {
  background: rgba(18, 38, 27, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

/* ---- 实验探究控制台与交互组件 ---- */
.nt-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-soft);
}

html[data-variant="opening"] .nt-controls {
  background: rgba(18, 38, 27, 0.8);
  border-color: var(--border);
}

.nt-btn {
  appearance: none;
  border: 1px solid var(--border-strong);
  background: #FFFFFF;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.18s ease;
  outline: none;
}

.nt-btn:hover {
  border-color: var(--accent-green);
  background: var(--accent-green-subtle);
  color: var(--accent-green);
}

.nt-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.nt-btn[aria-pressed="true"] {
  background: var(--accent-green);
  border-color: var(--accent-green);
  color: #FFFFFF;
}

html[data-variant="opening"] .nt-btn {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
  border-color: var(--border);
}

html[data-variant="opening"] .nt-btn:hover {
  background: var(--accent-green-subtle);
  border-color: #3EB361;
  color: #3EB361;
}

html[data-variant="opening"] .nt-btn[aria-pressed="true"] {
  background: #2A7E43;
  border-color: #2A7E43;
  color: #FFFFFF;
}

/* ---- 探究滑块 ---- */
.nt-slider-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.nt-slider-group label {
  font-size: var(--fs-label);
  color: var(--muted);
  display: flex;
  justify-content: space-between;
}

.nt-slider {
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  border-radius: 3px;
  outline: none;
}

.nt-slider::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-green);
  border: 2px solid #FFFFFF;
  cursor: pointer;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
}

/* ---- 生物反应流与化学式标签 ---- */
.nt-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-label);
  font-weight: 500;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
}

.nt-badge-green {
  background: var(--accent-green-subtle);
  color: var(--accent-green);
  border-color: rgba(42, 126, 67, 0.25);
}

.nt-badge-gold {
  background: var(--accent-gold-subtle);
  color: var(--accent-gold);
  border-color: rgba(217, 130, 43, 0.25);
}

.nt-badge-blue {
  background: var(--accent-blue-subtle);
  color: var(--accent-blue);
  border-color: rgba(43, 122, 140, 0.25);
}

.nt-formula {
  font-family: var(--font-mono);
  background: rgba(0, 0, 0, 0.03);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.95em;
  border: 1px solid var(--border);
}

html[data-variant="opening"] .nt-formula {
  background: rgba(255, 255, 255, 0.08);
}

/* ---- 反应速率影响曲线与科学图表通用规则 ---- */
.nt-chart {
  position: relative;
  width: 100%;
  height: 100%;
}

.nt-chart svg {
  display: block;
  overflow: visible;
}

.nt-chart-axis {
  stroke: var(--border-strong);
  stroke-width: 1.5px;
}

.nt-chart-grid {
  stroke: var(--border);
  stroke-width: 1px;
  stroke-dasharray: 3 3;
}

.nt-chart-label {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  fill: var(--muted);
}

.nt-chart-tick {
  font-family: var(--font-mono);
  font-size: var(--fs-tick);
  fill: var(--muted);
}

.nt-chart-curve {
  fill: none;
  stroke-width: 3px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nt-chart-curve-green {
  stroke: var(--accent-green);
}

.nt-chart-curve-gold {
  stroke: var(--accent-gold);
}

.nt-chart-curve-red {
  stroke: var(--accent-red);
}

.nt-chart-point {
  fill: #FFFFFF;
  stroke-width: 2.5px;
}

.nt-chart-point-green {
  stroke: var(--accent-green);
}

.nt-chart-point-gold {
  stroke: var(--accent-gold);
}

/* 动效友好与无障碍 */
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
